Translate("frFR", "elwynn-forest", {
	title = "Forêt d'Elwynn",
	aliases = { "Elwynn" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Forêt d'Elwynn est le cœur verdoyant du {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Ses chênes se pressent autour des murs blancs de la capitale, et entre eux s'étendent des lacs paisibles, des champs dorés et de vieilles mines qui nourrissent le royaume depuis des générations. Pour les gens de {link:stormwind-city}Stormwind{/link}, Elwynn a toujours été le lieu le plus sûr du monde. Cette croyance s'effrite désormais. Les loups rôdent plus près des fermes à chaque saison, d'étranges choses remuent dans les mines, et les routes qui ne connaissaient jadis que marchands et pèlerins connaissent aujourd'hui les voleurs.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte l'année où les premiers humains s'établirent à Elwynn. Ce que l'on sait, c'est que la forêt fut prise bien des siècles avant l'ouverture de la {link:dark-portal}Porte des Ténèbres{/link}. Quand l'antique empire d'{link:arathor}Arathor{/link} mit fin à sa longue unité, de hardies familles de la lignée arathie partirent vers le sud en quête de nouvelles terres. Parmi les bois riches et les rivières qu'elles y trouvèrent, elles fondèrent un royaume qu'elles nommèrent {link:azeroth}Azeroth{/link}, et en son cœur une cité appelée {link:stormwind-city}Stormwind{/link}. Elwynn devint le grenier et le jardin du royaume. Au nord de la cité, les clercs de l'abbaye de {link:northshire-abbey}Northshire{/link} entretenaient la foi en la {link:holy-light}Lumière sacrée{/link}, et leur abbaye devint l'un de ses plus anciens foyers dans le sud.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Elwynn a repoussé sur les cendres de la guerre, mais elle est mal gardée. Le roi {link:varian-wrynn}Varian Wrynn{/link} a disparu, et nul ne sait où il est allé. En son absence, le généralissime {link:bolvar-fordragon}Bolvar Fordragon{/link} gouverne en régent, et les forces du royaume sont dispersées sur une douzaine de frontières troublées. Des {link:kobolds}kobolds{/link} se sont emparés des mines de {link:fargodeep-mine}Fargodeep{/link} et de {link:jasperlode-mine}Jasperlode{/link}. Des {link:riverpaw-gnolls}gnolls Rivepatte{/link} font des raids par la frontière sud. Des bandits de la {link:defias-brotherhood}Confrérie défias{/link} s'en prennent aux fermes proches de la {link:westfall}Marche de l'Ouest{/link}. Les quelques maréchaux de {link:goldshire}Goldshire{/link} ne peuvent plus tenir seuls la forêt, et ils accueillent toute épée prête à servir.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les gens de {link:stormwind-city}Stormwind{/link}.{/b} Les fermiers, les bûcherons du {link:eastvale-logging-camp}Val d'est{/link} et les mineurs des collines restent parce que la terre est bonne, et parce qu'ils n'ont nulle part où aller.
• {b}Le clergé et les recrues de {link:northshire-abbey}Northshire{/link}.{/b} À l'abbaye, prêtres et paladins forment les jeunes hommes et les jeunes femmes qui défendront le royaume.
• {b}Les kobolds.{/b} Ils creusent dans les mines. Ils craignent l'obscurité par-dessus tout et gardent leurs bougies avec une ferveur sauvage.
• {b}Les {link:riverpaw-gnolls}gnolls Rivepatte{/link}.{/b} Ils descendent des collines du sud et des {link:redridge-mountains}Carmines{/link}, affamés de nourriture et de butin.
• {b}La {link:defias-brotherhood}Confrérie défias{/link}.{/b} Ses rangs commencèrent avec des hommes qui rebâtirent jadis Stormwind, et qui prennent aujourd'hui au couteau ce que la couronne leur doit encore, croient-ils.
• {b}Les murlocs.{/b} Les tribus {link:murlocs}murlocs{/link} hantent les rives du {link:crystal-lake}Lac de Cristal{/link} et du {link:stone-cairn-lake}Lac du Cairn{/link}, comme elles le font de mémoire d'homme.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La longue paix.{/b} Pendant des générations, Elwynn ne connut guère que moissons et fêtes. Ses villages s'enrichirent du commerce qui passait par {link:stormwind-city}Stormwind{/link}.
• {b}La Première Guerre.{/b} Puis la {link:horde}Horde{/link} orque franchit la {link:dark-portal}Porte des Ténèbres{/link}, et les terres d'{link:azeroth}Azeroth{/link} furent les premières à brûler. Pendant la {link:first-war}Première Guerre{/link}, la Horde livra aux flammes les fermes et les forêts d'Elwynn, et même les salles sacrées de l'abbaye de {link:northshire-abbey}Northshire{/link} n'y échappèrent pas. Enfin, Stormwind elle-même fut mise à sac, et le roi {link:llane-wrynn}Llane Wrynn{/link} fut tué dans son propre donjon. Sire {link:anduin-lothar}Anduin Lothar{/link} mena les survivants au nord, par-delà la mer, jusqu'en {link:lordaeron}Lordaeron{/link}, et avec eux partit le jeune fils du roi, {link:varian-wrynn}Varian{/link}.
• {b}Le retour.{/b} Après la {link:second-war}Deuxième Guerre{/link}, les exilés rentrèrent chez eux. Ils replantèrent la forêt et rebâtirent les villages. La {link:stonemasons-guild}guilde des Maçons{/link}, menée par {link:edwin-vancleef}Edwin VanCleef{/link}, releva Stormwind de ses décombres. Quand la {link:house-of-nobles}Chambre des nobles{/link} refusa de payer les maçons pour leur labeur, ceux-ci se soulevèrent dans les rues. La reine {link:tiffin-wrynn}Tiffin Wrynn{/link} fut parmi ceux qui périrent dans le chaos. Les maçons furent chassés de la cité, et de leur amertume naquit la {link:defias-brotherhood}Confrérie défias{/link}.
• {b}Le temps présent.{/b} Aujourd'hui, le roi est parti, les armées sont loin, et Elwynn s'en remet au courage d'une poignée de maréchaux et de volontaires.]=],
		},
		{
			title = "Légendes de la forêt",
			text = [=[• Chez les kobolds d'Elwynn, aucun crime n'est plus grave que de voler une bougie. Tout mineur qui a travaillé sous terre connaît le cri qui suit un tel vol.
• Les familles Maclure et Stonefield se querellent de part et d'autre de la même clôture depuis plus longtemps que l'une ou l'autre ne s'en souvient. Pourtant, on murmure à {link:goldshire}Goldshire{/link} qu'une fille Maclure et un fils Stonefield se retrouvent en secret quand les champs sont sombres.
• La {link:tower-of-azora}Tour d'Azora{/link} s'élève à l'est de la forêt. C'est la demeure d'un mage dont les gens simples d'Elwynn ne comprennent pas les études, et sur lesquelles ils ne tiennent pas à poser de questions.
• Les fermiers du sud parlent de {link:hogger}Hogger{/link} à voix basse. C'est un {link:gnolls}gnoll{/link} si grand et si rusé que la prime sur sa tête n'a pas été réclamée depuis bien des saisons.]=],
		},
	},
})

Translate("frFR", "northshire-abbey", {
	title = "Abbaye de Northshire",
	aliases = { "Northshire" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'abbaye de Northshire se dresse au bout d'une vallée abritée, au nord de {link:stormwind-city}Stormwind{/link}. Depuis des siècles, c'est une maison de la {link:holy-light}Lumière sacrée{/link}, où les clercs priaient, soignaient et gardaient les vieux livres de leur foi. C'est ici que le jeune {link:medivh}Medivh{/link} resta des années plongé dans un sommeil qu'aucun guérisseur ne put rompre, veillé par les frères de l'abbaye. Pendant la {link:first-war}Première Guerre{/link}, la {link:horde}Horde{/link} l'incendia, mais les fidèles revinrent et relevèrent ses murs. Aujourd'hui, c'est un terrain d'entraînement. Les recrues viennent y apprendre l'épée, le sort et la prière avant d'être envoyées dans une forêt qui a besoin d'elles.]=],
		},
		{
			title = "La vallée",
			text = [=[La vallée n'est plus paisible. Des {link:kobolds}kobolds{/link} ont creusé la Mine de la crête aux échos au-dessus de l'abbaye. Des voleurs aux bandanas rouges se cachent parmi les ceps des Vignes de Northshire, et leur chef tient une cabane à la lisière est de la vallée. Des loups descendent des collines. Les frères de Northshire ont appris que même une terre sacrée doit être gardée.]=],
		},
	},
})

Translate("frFR", "goldshire", {
	title = "Goldshire",
	sections = {
		{
			title = "Résumé",
			text = [=[Goldshire est le carrefour d'{link:elwynn-forest}Elwynn{/link}. Ses routes mènent au nord vers l'abbaye, au sud vers les fermes, à l'est vers les camps de bûcherons et à l'ouest vers la {link:westfall}Marche de l'Ouest{/link}. En son cœur se dresse le Lion's Pride Inn, où la famille Farley sert de la bière aux voyageurs depuis aussi longtemps que s'en souviennent les plus vieux habitants. La ville a un forgeron, une écurie et un apothicaire. C'est aussi le poste du maréchal {link:marshal-dughan}Dughan{/link}, dont les quelques soldats doivent répondre de la sécurité de toute la forêt.]=],
		},
		{
			title = "De nos jours",
			text = [=[L'auberge bruit de rumeurs. Les marchands parlent de poudre d'or achetée aux mines, de murlocs enhardis sur les rives des lacs, de gnolls sur la route du sud. Les plus vieux habitants de Goldshire se souviennent encore de la fumée de la {link:first-war}Première Guerre{/link}. Les plus jeunes commencent à comprendre ce que leurs aînés voulaient dire.]=],
		},
	},
})

Translate("frFR", "fargodeep-mine", {
	title = "Mine de Fargodeep",
	aliases = { "Fargodeep" },
	sections = {
		{
			title = "Résumé",
			text = [=[Fargodeep fut jadis une mine d'or de la couronne. Elle se trouve dans les collines du sud d'{link:elwynn-forest}Elwynn{/link}, entre les terres des Stonefield et celles des Maclure. Quand les mineurs la quittèrent, les {link:kobolds}kobolds{/link} arrivèrent. Ses tunnels vacillent désormais à la lueur des bougies d'une garenne kobolde, et l'on dit que le kobold {link:goldtooth}Goldtooth{/link} amasse des trésors volés dans ses profondeurs. Quoi que les kobolds cherchent à atteindre en creusant, ils creusent avec ardeur.]=],
		},
	},
})

Translate("frFR", "jasperlode-mine", {
	title = "Mine de Jasperlode",
	aliases = { "Jasperlode" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Mine de Jasperlode se trouve dans les collines de l'est, au nord de la {link:tower-of-azora}Tour d'Azora{/link}. Ce fut l'une des mines qui alimentaient les forges de {link:stormwind-city}Stormwind{/link}. Des kobolds tiennent désormais ses tunnels supérieurs. Plus bas encore, là où même les kobolds ne vont pas de bon gré, de grandes araignées des mines tissent leurs toiles dans le noir. Les mineurs qui ont fui Jasperlode parlent plus des araignées que des kobolds.]=],
		},
	},
})

Translate("frFR", "tower-of-azora", {
	title = "Tour d'Azora",
	aliases = { "Azora" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Tour d'Azora s'élève au-dessus des bois de l'est d'{link:elwynn-forest}Elwynn{/link}. C'est le siège du mage {link:theocritus}Theocritus{/link} et des gnomes qui le servent. De sa plus haute salle, un instrument de divination appelé l'Œil d'Azora regarde loin vers l'est, vers la {link:tower-of-ilgalar}Tour d'Ilgalar{/link} dans les {link:redridge-mountains}Carmines{/link}. Là demeure le démoniste {link:morganth}Morganth{/link}, dont Theocritus a juré de surveiller et de contrecarrer les sombres études. Les gens de la forêt se tiennent à l'écart des deux tours.]=],
		},
	},
})

Translate("frFR", "brackwell-pumpkin-patch", {
	title = "Champ de potirons des Brackwell",
	aliases = { "Brackwell" },
	sections = {
		{
			title = "Résumé",
			text = [=[La ferme des Brackwell se trouve dans le sud-est d'{link:elwynn-forest}Elwynn{/link}, là où une famille cultivait jadis des potirons célèbres dans toute la forêt. Les Brackwell sont partis, et nul ne sait ce qu'il est advenu d'eux. La {link:defias-brotherhood}Confrérie défias{/link} tient désormais la ferme. On dit que l'or pris aux mines des kobolds y transite en route vers un agent défias appelé le Collecteur. Il ne reste qu'un seul trésor des Brackwell : Princesse, leur truie primée, devenue énorme grâce aux légumes de ses voisins.]=],
		},
	},
})

Translate("frFR", "eastvale-logging-camp", {
	title = "Camp de bûcherons du Val d'est",
	aliases = { "Val d'est" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Val d'est est le camp de bûcherons d'{link:elwynn-forest}Elwynn{/link}, à la lisière est de la forêt, près de la route des {link:redridge-mountains}Carmines{/link}. Ses bûcherons fournissent le bois qui rebâtit {link:stormwind-city}Stormwind{/link}, et ils envoient encore des chariots vers l'ouest à chaque saison. Le camp vit sous la menace constante des loups et des ours. Le garde {link:guard-thomas}Thomas{/link} tient le pont à l'ouest, et le vieux manoir du maréchal {link:marshal-haggard}Haggard{/link} se dresse tout près.]=],
		},
	},
})

Translate("frFR", "stone-cairn-lake", {
	title = "Lac du Cairn",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac du Cairn est un anneau d'eau autour d'une île boisée, au nord-est de la forêt. Sur sa rive se dresse la Veillée des héros, où un cairn de pierres rappelle les hommes et les femmes de {link:goldshire}Goldshire{/link} et de ses fermes morts pendant la {link:first-war}Première Guerre{/link}. C'est un lieu de deuil. Ce n'est plus un lieu de paix : des sorciers renégats ont pris l'île, et des murlocs chassent le long de la rive sud.]=],
		},
	},
})

Translate("frFR", "maclure-vineyards-and-stonefield-farm", {
	title = "Vignes des Maclure et ferme des Stonefield",
	aliases = { "Les Vignes des Maclure", "La ferme des Stonefield" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dans le sud d'{link:elwynn-forest}Elwynn{/link}, deux fermes se font face de part et d'autre d'une étroite bande de terre. À l'est poussent les vignes des Maclure. À l'ouest se trouvent les champs et la maison des Stonefield. Les deux familles sont en guerre depuis plus longtemps que ne s'en souvient aucun de leurs enfants, et la cause en est depuis longtemps enfouie sous les insultes, les biens volés et les portes claquées. Pourtant, entre la vigne et la ferme court un sentier tranquille, et tous ceux qui l'empruntent ne le font pas avec colère.]=],
		},
	},
})

Translate("frFR", "crystal-lake", {
	title = "Lac de Cristal",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lac de Cristal s'étend à l'est de {link:goldshire}Goldshire{/link}, calme et clair comme son nom. Ses eaux nourrissent un varech rare qui scintille comme du verre, prisé des apothicaires pour ses étranges propriétés. Les murlocs du lac le gardent jalousement. Les pêcheurs qui y jetaient jadis leurs filets se tiennent désormais sur la rive opposée.]=],
		},
	},
})

Translate("frFR", "westbrook-garrison", {
	title = "Garnison du ruisseau de l'ouest",
	aliases = { "Ruisseau de l'ouest" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Garnison du ruisseau de l'ouest garde la lisière ouest d'{link:elwynn-forest}Elwynn{/link}, là où la forêt cède la place aux champs de la {link:westfall}Marche de l'Ouest{/link}. Ses casernes furent bâties pour maintenir la paix de la frontière. Elles peinent désormais à maintenir quoi que ce soit. Des voleurs viennent de l'ouest, et les {link:riverpaw-gnolls}gnolls Rivepatte{/link} de La Lisière attaquent par le sud. Au tableau d'affichage de la garnison pend une affiche que chaque soldat connaît par cœur : une récompense pour la tête de {link:hogger}Hogger{/link}.]=],
		},
	},
})

Translate("frFR", "marshal-mcbride", {
	title = "Maréchal McBride",
	subtitle = "Maréchal de Northshire",
	found = "À l'intérieur de l'abbaye de Northshire",
	hint = "Parlez au maréchal qui commande les recrues de Northshire.",
	allegiance = "Royaume de Stormwind · Armée de Stormwind",
	aliases = { "McBride" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maréchal Douglas McBride commande les recrues de l'abbaye de {link:northshire-abbey}Northshire{/link}. Chaque nouveau défenseur de {link:stormwind-city}Stormwind{/link} passe d'abord entre ses mains. Il doit faire des soldats de fils de fermiers et de filles de commis, et il doit le faire alors que l'armée du royaume est loin et que la vallée elle-même est menacée.]=],
		},
		{
			title = "Importance",
			text = [=[McBride est le premier officier de {link:stormwind-city}Stormwind{/link} que rencontrent la plupart des nouvelles recrues. Il voit clairement ce que la cour de la capitale ne veut pas dire tout haut : l'armée étant rassemblée à l'étranger, les hors-la-loi se sont enhardis dans le royaume, et son cœur doit être défendu par ses soldats les plus neufs et les moins éprouvés.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il forme les recrues de {link:northshire-abbey}Northshire{/link} et les met à l'épreuve face aux dangers de la vallée.
• Il envoie des patrouilles contre les kobolds de la Mine de la crête aux échos.
• Il rédige les rapports qui portent de Northshire à {link:goldshire}Goldshire{/link} les nouvelles des kobolds, des voleurs et des loups.]=],
		},
	},
	chapters = {
		{
			title = "Les kobolds de la crête aux échos",
			hint = [=[Repoussez les kobolds dans les profondeurs de la Mine de la crête aux échos.]=],
			text = [=[Les premiers kobolds n'étaient qu'une nuisance qu'on chassait avec des torches. Puis les recrues revinrent de la Mine de la crête aux échos avec des récits de garennes entières sous la vallée. McBride commença à se demander depuis combien de temps les kobolds creusaient là, et ce qu'ils risquaient encore de trouver.]=],
		},
		{
			title = "Des papiers pour Goldshire",
			hint = "Portez les documents du maréchal à Goldshire.",
			text = [=[Les papiers que McBride scelle pour {link:goldshire}Goldshire{/link} racontent l'histoire de la vallée en simples mots de soldat : des kobolds à la crête aux échos, une confrérie de voleurs aux bandanas rouges, et des loups chassés de l'est. Ils portent aussi son jugement sur la recrue qui les apporte. Ceux qu'il juge dignes deviennent adjoints des maréchaux de {link:stormwind-city}Stormwind{/link}.]=],
		},
	},
	mentions = {
		{ text = "Une menace intérieure" },
		{ text = "Nettoyage du camp {link:kobolds}kobold{/link}" },
		{ text = "Enquête à la crête aux échos" },
		{ text = "Escarmouche à la crête aux échos" },
		{ text = "Rapport à {link:goldshire}Goldshire{/link}" },
		{
			text = [=[Vue d'ensemble, les livres volés de {link:northshire-abbey}Northshire{/link}]=],
		},
		{ text = "Suivez ce {link:kobolds}kobold{/link} !" },
		{ text = "Une lettre griffonnée" },
		{ text = "L'aventurier" },
	},
	bonds = {
		{ id = "deputy-willem", name = "Adjoint Willem", note = "garde la porte de l'abbaye" },
		{ id = "brother-paxton", name = "Frère Paxton", note = "garde la bibliothèque de l'abbaye" },
		{ id = "tordrin-sternblade", name = "Tordrin Sternblade", note = "le chasseur qu'il envoie après les voleurs" },
		{ id = "marshal-dughan", name = "Maréchal Dughan", note = "reçoit ses recrues" },
		{ id = "brother-sammuel", name = "Frère Sammuel", note = "forme les paladins de l'abbaye" },
	},
})

Translate("frFR", "deputy-willem", {
	title = "Adjoint Willem",
	subtitle = "Adjoint de Northshire",
	found = "Devant les portes de l'abbaye de Northshire",
	hint = [=[Parlez à l'adjoint qui se tient devant les portes de l'abbaye.]=],
	allegiance = "Royaume de Stormwind · Armée de Stormwind",
	aliases = { "Willem" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'adjoint Willem monte la garde devant les portes de l'abbaye de {link:northshire-abbey}Northshire{/link}. Il accueille chaque recrue qui arrive, et il est souvent le premier à lui dire combien la vallée a besoin d'aide. Il préférerait traquer lui-même les voleurs, mais son poste est à la porte.]=],
		},
		{
			title = "Importance",
			text = [=[Willem est le premier visage du service de {link:stormwind-city}Stormwind{/link} pour bien des jeunes défenseurs. Par lui, ils apprennent l'existence des voleurs aux bandanas rouges qui se sont glissés dans la vallée.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il offre une récompense pour les bandanas rouges des voleurs des Vignes de {link:northshire-abbey}Northshire{/link}.
• Il met à prix la tête du voleur {link:garrick-padfoot}Garrick Padfoot{/link}.
• Il envoie les recrues auprès du chasseur Eagan Peltskinner et de la vigneronne {link:milly-osworth}Milly Osworth{/link}.]=],
		},
	},
	mentions = {
		{ text = "Une menace intérieure" },
		{ text = "La confrérie des voleurs" },
		{ text = "{link:garrick-padfoot}Garrick Padfoot{/link}, mort ou vif" },
		{ text = "Eagan Peltskinner" },
		{ text = "{link:milly-osworth}Milly Osworth{/link}" },
	},
	bonds = {
		{ id = "marshal-mcbride", name = "Maréchal McBride", note = "son commandant" },
		{ id = "garrick-padfoot", name = "Garrick Padfoot", note = "le voleur qu'il veut voir pris" },
		{ id = "milly-osworth", name = "Milly Osworth", note = "le tient pour un homme courageux" },
	},
})

Translate("frFR", "brother-sammuel", {
	title = "Frère Sammuel",
	subtitle = "Maître des paladins",
	found = "La salle d'armes, à l'intérieur de l'abbaye de Northshire",
