Translate("frFR", "marshal-dughan", {
	title = "Maréchal Dughan",
	subtitle = "Maréchal de Goldshire",
	found = "Goldshire, devant le Lion's Pride Inn",
	hint = "Parlez au maréchal qui veille sur Goldshire.",
	allegiance = "Royaume de Stormwind · Armée de Stormwind",
	aliases = { "Dughan" },
	sections = {
		{
			title = "Résumé",
			text = [=[Depuis la ville-carrefour de {link:goldshire}Goldshire{/link}, le maréchal Dughan commande la défense de la {link:elwynn-forest}Forêt d'Elwynn{/link}. Ses soldats sont trop peu nombreux pour la tâche. Pourtant, il doit garder ouvertes les routes qui relient la capitale à ses fermes, à ses moulins et à ses mines. Chaque recrue qui quitte l'abbaye de {link:northshire-abbey}Northshire{/link} passe entre ses mains, et il envoie chacune là où la forêt saigne le plus.]=],
		},
		{
			title = "Importance",
			text = [=[Dughan est le visage d'un royaume poussé à ses limites. {link:stormwind-city}Stormwind{/link} n'a pas de roi sur le trône, pas d'armée à portée de main, et seulement la loyauté d'hommes et de femmes ordinaires pour garder sa paix. Il ne s'en plaint pas. Il fait simplement le travail qui reste.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il tient {link:elwynn-forest}Elwynn{/link} avec une poignée de soldats, répartis entre {link:goldshire}Goldshire{/link}, la {link:westbrook-garrison}Garnison du ruisseau de l'ouest{/link} et le {link:eastvale-logging-camp}Val d'est{/link}.
• Il envoie des éclaireurs dans les mines de {link:fargodeep-mine}Fargodeep{/link} et de {link:jasperlode-mine}Jasperlode{/link}, où les kobolds s'enhardissent chaque jour.
• Il met à prix la tête du {link:gnolls}gnoll{/link} {link:hogger}Hogger{/link} et celles des pillards {link:riverpaw-gnolls}Rivepatte{/link} de la frontière sud.
• Il envoie l'aide qu'il peut aux postes isolés de la forêt, bien qu'il en ait rarement à revendre.]=],
		},
		{
			title = "Non consigné",
			text = [=[On sait peu de choses de la vie de Dughan avant {link:goldshire}Goldshire{/link}. Cette entrée ne rapporte que ce que révèlent ses actes et son poste.]=],
		},
	},
	chapters = {
		{
			title = "Les recrues de Northshire",
			hint = [=[Terminez votre formation à Northshire et présentez-vous à Goldshire.]=],
			text = [=[Les recrues arrivent avec des lettres du maréchal {link:marshal-mcbride}McBride{/link}. Dughan a peu de temps pour les accueillir, car les kobolds tiennent les mines, les gnolls rôdent sur la frontière et les voleurs hantent chaque route. Il met chaque nouveau venu au travail dans l'heure.]=],
		},
		{
			title = "Sous les collines",
			hint = "Enquêtez sur les mines d'Elwynn pour le compte du maréchal.",
			text = [=[Les rapports de {link:fargodeep-mine}Fargodeep{/link} et de {link:jasperlode-mine}Jasperlode{/link} confirment ce que Dughan craignait. Les kobolds ne sont plus une nuisance qu'on chasse avec des torches. Ils se répandent, et ils creusent plus profond qu'aucun mineur honnête n'a jamais osé le faire.]=],
		},
		{
			title = "La frontière sud",
			hint = "Réglez l'affaire de Hogger.",
			text = [=[Longtemps, on raconta les histoires de {link:hogger}Hogger{/link} comme des contes de veillée. Dughan cessa de les tenir pour des contes quand les morts commencèrent à revenir des fermes du sud.]=],
		},
		{
			title = "Le Collecteur",
			hint = "Suivez l'or volé des mines jusqu'au bout.",
			text = [=[La poudre d'or volée dans les mines ne reste pas chez les kobolds. Elle voyage par des routes cachées jusqu'à un agent défias connu seulement comme le Collecteur. Quand on trouve la chevalière du Collecteur, elle porte la marque de l'ancienne {link:stonemasons-guild}guilde des Maçons{/link} de {link:stormwind-city}Stormwind{/link}. Dughan comprend alors que les voleurs d'{link:elwynn-forest}Elwynn{/link} ne sont pas de simples bandits. Ce sont les maçons que Stormwind a trahis.]=],
		},
	},
	mentions = {
		{
			text = [=[Rapport à {link:goldshire}Goldshire{/link}, apporté de la part du maréchal {link:marshal-mcbride}McBride{/link}]=],
		},
		{ text = "La {link:fargodeep-mine}Mine de Fargodeep{/link}" },
		{ text = "La {link:jasperlode-mine}Mine de Jasperlode{/link}" },
		{
			text = [=[La {link:westbrook-garrison}Garnison du ruisseau de l'ouest{/link} a besoin d'aide !]=],
		},
		{
			text = [=[Avis de recherche : {link:hogger}Hogger{/link}, une prime payée de sa main]=],
		},
		{
			text = [=[Un péril poissonneux, apporté par {link:remy-two-times}Remy « Deux-Fois »{/link}]=],
		},
		{ text = "Chasse à l'homme" },
		{ text = "Chut ! On chasse les kobolds" },
		{ text = "Retour de livres" },
		{ text = "Livres rares" },
	},
	bonds = {
		{ id = "marshal-mcbride", name = "Maréchal McBride", note = "lui envoie des recrues" },
		{ id = "deputy-rainer", name = "Adjoint Rainer", note = "tient la Garnison du ruisseau de l'ouest" },
		{ id = "guard-thomas", name = "Garde Thomas", note = "veille sur le Val d'est" },
		{ id = "remy-two-times", name = "Remy « Deux-Fois »", note = "lui apporte des nouvelles" },
		{ id = "hogger", name = "Hogger", note = "ennemi" },
	},
})

