Translate("frFR", "marshal-haggard", {
	title = "Maréchal Haggard",
	subtitle = "Maréchal de Stormwind à la retraite",
	found = "Son manoir près du Val d'est",
	hint = "Rendez visite au vieux maréchal qui vit près du Val d'est.",
	allegiance = "Royaume de Stormwind (à la retraite)",
	aliases = { "Haggard" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maréchal Haggard servit {link:stormwind-city}Stormwind{/link} de nombreuses années avant de se retirer dans un manoir près du {link:eastvale-logging-camp}Val d'est{/link}. Ses yeux ont faibli avec l'âge, mais pas sa fierté. Il garde toujours l'insigne de sa charge, et il connaît toujours de vieilles histoires que les jeunes soldats ont oubliées.]=],
		},
		{
			title = "Importance",
			text = [=[Haggard est une mémoire vivante de l'ancienne {link:stormwind-city}Stormwind{/link}. Sa maison détient aussi le premier fil d'une histoire plus sombre, qui mène à l'est, dans le {link:duskwood}Bois de la Pénombre{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il servit comme maréchal de {link:stormwind-city}Stormwind{/link} jusqu'à sa retraite.
• Il connaît la vieille histoire d'un homme appelé {link:stalvan-mistmantle}Stalvan{/link}, une histoire qui commence par une caisse scellée trouvée dans les canaux de Stormwind.]=],
		},
	},
	chapters = {
		{
			title = "Le voleur dans le noir",
			hint = "Récupérez ce qui a été pris au vieux maréchal.",
			text = [=[Une nuit, un homme portant un tabard de {link:stormwind-city}Stormwind{/link} vint à la porte de Haggard. Dans l'obscurité, le vieux maréchal le prit pour {link:marshal-dughan}Dughan{/link} et lui remit son insigne. Le visiteur n'était pas maréchal. C'était un voleur défias appelé Dead-tooth Jack, et il disparut avec l'insigne avant l'aube.]=],
		},
		{
			title = "La caisse scellée",
			hint = [=[Apportez au vieux maréchal ce qui fut trouvé dans une caisse scellée des canaux de Stormwind.]=],
			text = [=[Une caisse scellée, longtemps oubliée dans les canaux de {link:stormwind-city}Stormwind{/link}, contenait des papiers qui menaient au maréchal Haggard. Quand ils lui parvinrent, le vieux maréchal reconnut le nom dont ils parlaient. Cela ouvrit une histoire qu'il aurait préféré ne pas se rappeler : la légende de {link:stalvan-mistmantle}Stalvan Mistmantle{/link}, un nom que l'on murmure encore avec effroi dans le {link:duskwood}Bois de la Pénombre{/link}.]=],
		},
	},
	mentions = {
		{ text = "Maréchal Haggard" },
		{ text = "Dead-tooth Jack" },
		{ text = "La légende de {link:stalvan-mistmantle}Stalvan{/link}" },
	},
	bonds = {
		{ id = "guard-thomas", name = "Garde Thomas", note = "garde le pont voisin" },
		{ id = "marshal-dughan", name = "Maréchal Dughan", note = "l'homme qu'il crut voir" },
	},
})

Translate("frFR", "guard-thomas", {
