})

Translate("frFR", "maybell-maclure", {
	title = "Maybell Maclure",
	subtitle = "Fille des Maclure",
	found = "Les Vignes des Maclure",
	hint = "Parlez à la jeune femme des Vignes des Maclure.",
	allegiance = "Famille Maclure",
	aliases = { "Maybell" },
	sections = {
		{
			title = "Résumé",
			text = [=[Maybell est la fille de la famille Maclure. Son cœur appartient à {link:tommy-joe-stonefield}Tommy Joe Stonefield{/link}, le fils de la famille que les siens haïssent depuis des générations. Elle ne renoncera pas à lui, et elle n'attendra pas que la querelle prenne fin d'elle-même.]=],
		},
