Translate("frFR", "camping", {
	title = "Campement",
	sections = {
		{
			title = "Résumé",
			text = [=[Le campement est le vieil art de la route : faire un feu dans la nature, le partager, et se reposer à ses côtés avant de reprendre le voyage. Les voyageurs de tout {link:azeroth}Azeroth{/link} ont toujours su qu'une nuit près d'un bon feu peut faire la différence entre atteindre la ville suivante et ne jamais l'atteindre.]=],
		},
		{
			title = "Le feu et les métiers",
			text = [=[Un camp commence par un feu de camp, bâti par ceux qui connaissent l'art de la cuisine. D'autres voyageurs peuvent ensuite y ajouter quelque chose, chacun selon le métier qu'il connaît. Un forgeron installe une meule à aiguiser. Un travailleur du cuir dresse une tente. Un alchimiste, un enchanteur, un mineur ou un tailleur apporte chacun quelque chose de sien : un puits de mana, un luth enchanté, une pierre d'aimant, une bannière de son peuple. Les plus grandes de ces œuvres se bâtissent à partir de plans gardés par les maîtres de chaque métier, et certains de ces plans seraient entre les mains d'ennemis dangereux.]=],
		},
		{
			title = "La coutume du feu",
			text = [=[Selon la coutume, chaque voyageur ajoute une seule œuvre à un feu partagé, et aucun métier n'est installé deux fois auprès des mêmes flammes. Ceux qui s'assoient un moment près d'un tel feu s'en relèvent revigorés, et ils en emportent le bienfait des heures durant sur la route.]=],
		},
	},
})
